CREATE TABLE IF NOT EXISTS admins(id BIGSERIAL PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,price_paise INTEGER NOT NULL CHECK(price_paise>=0),size TEXT,category TEXT,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,customer_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,address TEXT NOT NULL,city TEXT NOT NULL,state TEXT NOT NULL,pin TEXT NOT NULL,payment_method TEXT NOT NULL,payment_status TEXT DEFAULT 'pending',order_status TEXT DEFAULT 'pending',total_paise INTEGER NOT NULL,razorpay_order_id TEXT,razorpay_payment_id TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items(id BIGSERIAL PRIMARY KEY,order_id TEXT REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT REFERENCES products(id),product_name TEXT NOT NULL,unit_price_paise INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0));
